def demand(p, a=10.0, b=1.0):
    return max(a - b * p, 0.0)


def monopoly_profit(p, a=10.0, b=1.0, c=2.0):
    return (p - c) * demand(p, a=a, b=b)


def monopoly_price(a=10.0, b=1.0, c=2.0):
    return (a + b * c) / (2 * b)


